using System.Linq.Expressions;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using Vixly.Operations.Domain.Common;
using Vixly.Shared.Kernel.Domain;

namespace Vixly.Operations.Infrastructure.Persistence.Conventions;

// =========================================================
// FILE: OperationsModelConventions.cs
//
// PURPOSE:
// Model rules every Operations entity follows (D-5, D-F1).
//
// RESPONSIBILITIES:
// - Keys set in code are never generated by the database (D-5)
// - Every tenant entity gets the tenant query filter and an index on TenantId
//
// IMPORTANT NOTES:
// - The filter reads the DbContext, so it is evaluated per query, never cached with a tenant baked in
// - System entities get no filter
// =========================================================
public static class OperationsModelConventions
{
    public static void Apply(ModelBuilder modelBuilder, OperationsDbContext context)
    {
        ArgumentNullException.ThrowIfNull(modelBuilder);
        ArgumentNullException.ThrowIfNull(context);

        foreach (IMutableEntityType entityType in modelBuilder.Model.GetEntityTypes().ToArray())
        {
            Type clrType = entityType.ClrType;

            if (typeof(AuditableEntity).IsAssignableFrom(clrType) && entityType.FindProperty(nameof(AuditableEntity.Id)) is { } id)
            {
                id.ValueGenerated = ValueGenerated.Never;
            }

            // Owned parts (a user account, its codes) are filtered through their owner; EF allows no filter on them.
            if (typeof(OperationsEntity).IsAssignableFrom(clrType) && entityType.BaseType is null && !entityType.IsOwned())
            {
                modelBuilder.Entity(clrType).HasQueryFilter(TenantFilter(clrType, context));
                modelBuilder.Entity(clrType).HasIndex(nameof(OperationsEntity.TenantId));
            }
        }
    }

    // =====================================================
    // METHOD: TENANT FILTER
    // =====================================================
    // entity => context.IgnoreTenantFilter || entity.TenantId == context.TenantFilterId
    private static LambdaExpression TenantFilter(Type clrType, OperationsDbContext context)
    {
        ParameterExpression entity = Expression.Parameter(clrType, "entity");
        ConstantExpression owner = Expression.Constant(context);
        Expression ignore = Expression.Property(owner, nameof(OperationsDbContext.IgnoreTenantFilter));
        Expression tenant = Expression.Property(owner, nameof(OperationsDbContext.TenantFilterId));
        Expression match = Expression.Equal(Expression.Property(entity, nameof(OperationsEntity.TenantId)), tenant);
        return Expression.Lambda(Expression.OrElse(ignore, match), entity);
    }
}
